import { kebabCase, keyBy } from 'es-toolkit';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function toSlug(label: string): string {
  return kebabCase(label);
}

export function byNameKey(rows: Row[]): Record<string, Row> {
  return keyBy(rows, r => r.name);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
cp out/module.ts out/m2.ts
npm run size -- src/module.ts | tail -1; npm run size -- out/module.ts | tail -1
cat > out/t.mjs <<'EOF'
import l from 'lodash/kebabCase.js'; import {kebabCase as k} from 'es-toolkit';
const ch='aAbBZz09 -_.'.split(''); let bad=0;
for(let i=0;i<200000;i++){let s='';const n=Math.floor(Math.random()*12);for(let j=0;j<n;j++)s+=ch[Math.floor(Math.random()*ch.length)];
 if(l(s)!==k(s)){if(bad++<5)console.log(JSON.stringify(s),l(s),k(s));}}
console.log('bad',bad)
EOF
node out/t.mjs

